#include "account_reference_page.hpp"
#include <QtWidgets>
#include "detail_disclosure.hpp"
#include "financial_delegate.hpp"
namespace {
QString displayValue(QJsonValue v){return v.isDouble()?QString::number(v.toDouble(),'g',15):v.isString()?v.toString():QString("未知");}
}
AccountReferencePage::AccountReferencePage(Reader r,QWidget*p):QWidget(p),reader(std::move(r)){
 setObjectName("accountReferencePage");auto*layout=new QVBoxLayout(this);auto*reloadButton=new QPushButton("刷新账本参考",this);reloadButton->setObjectName("accountReferenceReload");layout->addWidget(reloadButton);summary=new QLabel;summary->setObjectName("accountReferenceSummary");summary->setWordWrap(true);layout->addWidget(summary);
 rows=new QTableWidget(0,10);rows->setObjectName("accountReferenceContributions");rows->setHorizontalHeaderLabels({"证券","当日参考(元)","纳入旧当日汇总","累计贡献(元)","成本比例贡献(百分点)","期初股数","期末股数","当日现金流(元)","报价日期/时间","来源 / 状态"});rows->setEditTriggers(QAbstractItemView::NoEditTriggers);rows->setSelectionBehavior(QAbstractItemView::SelectRows);rows->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);layout->addWidget(rows,2);detail=new QPlainTextEdit;detail->setObjectName("accountReferenceDetail");detail->setReadOnly(true);addDataDetails(layout,detail,"accountReferenceDetails");financialVisual::install(rows,{1,3,4,7});
 connect(reloadButton,&QPushButton::clicked,this,[this]{reload();});connect(rows,&QTableWidget::cellClicked,this,[this](int at,int){if(at<0||!rows->item(at,0))return;auto row=rows->item(at,0)->data(Qt::UserRole).toJsonObject();detail->setPlainText("计算依据 / 缺数原因\n"+QString::fromUtf8(QJsonDocument(row).toJson(QJsonDocument::Indented)));});reload();
}
void AccountReferencePage::reload(){output={};rows->setRowCount(0);detail->clear();try{business::require(bool(reader),"宿主未接只读冻结输入");auto next=reader();business::require(next["schema"]=="native-account-reference/v1","参考盈亏结果格式无效");output=next;auto coverage=output["quoteCoverage"].toObject();summary->setText("账户 "+displayValue(output["accountId"])+" · 参考日期 "+displayValue(output["date"])+" · 资料截至 "+displayValue(output["asOf"])+"\n当日参考 "+displayValue(output["todayReferencePnl"])+" 元（旧未清仓范围） · 累计简单成本比例 "+displayValue(output["totalPnlRate"])+"% · 历次买入金额 "+displayValue(output["lifetimeBuyCost"])+" 元\n报价覆盖 "+displayValue(coverage["priced"])+"/"+displayValue(coverage["total"])+" · 匹配 "+displayValue(coverage["live"])+" · 旧/未核时点 "+displayValue(coverage["stale"])+" · 缺失 "+displayValue(coverage["missing"])+"\n成本比例不是时间加权收益率。");summary->setToolTip(output["boundary"].toString());
 for(auto v:output["contributions"].toArray()){auto r=v.toObject();int at=rows->rowCount();rows->insertRow(at);QStringList cells{displayValue(r["name"]),displayValue(r["todayReferencePnl"]),r["includedInLegacyDaily"].toBool()?"是":"否（已清仓）",displayValue(r["totalPnl"]),displayValue(r["totalPnlRateContribution"]),displayValue(r["openingQuantity"]),displayValue(r["endQuantity"]),displayValue(r["dayCashFlow"]),displayValue(r["quoteDate"])+" "+displayValue(r["quoteTime"]),displayValue(r["quoteSource"])+" / "+displayValue(r["quoteStatus"])};for(int col=0;col<cells.size();col++){auto*i=new QTableWidgetItem(cells[col]);i->setData(Qt::UserRole,r);i->setToolTip(r["instrumentId"].toString());rows->setItem(at,col,i);}}
 detail->setPlainText("点击证券查看完整计算依据。总计不包含已清仓证券的当日参考。\n"+QString::fromUtf8(QJsonDocument(QJsonObject{{"issues",output["issues"]},{"excludedFutureTrades",output["excludedFutureTrades"]}}).toJson(QJsonDocument::Indented)));
 }catch(const std::exception&e){output={};rows->setRowCount(0);summary->setText(QString::fromUtf8(e.what()));}}
void AccountReferencePage::setDarkTheme(bool dark){setStyleSheet(QString("QWidget{background:%1;color:%2;} QTableWidget,QPlainTextEdit{background:%3;} QPushButton{padding:5px;min-height:24px;}").arg(dark?"#111a26":"#ffffff",dark?"#dce5f0":"#243449",dark?"#172232":"#f4f7fb"));}

